INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22201, 'Matthew 6:34', 'Matthew', 6, 34, '&nbsp;ځکه د سبا غم مۀ کوئ، سبا به خپل غم په خپله کوى. د نن دپاره نننے غم کافى دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22202, 'Matthew 7:1', 'Matthew', 7, 1, '&nbsp;”په نورو اِلزام مۀ لګوئ نو په تاسو به هم اِلزام ونۀ لګولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22203, 'Matthew 7:2', 'Matthew', 7, 2, '&nbsp;ځکه چې څنګه تاسو په نورو اِلزامونه لګوئ دغه شان به په تاسو هم اِلزامونه ولګولے شى، نو چې څنګه تاسو د بل ناپ تول کوئ، دغه رنګ به ستاسو ناپ تول کولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22204, 'Matthew 7:3', 'Matthew', 7, 3, '&nbsp;تاسو د خپل ورور د سترګې خسڼى ته ولې ګوته نيسئ خو په خپله سترګه کښې درته تير نۀ ښکارى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22205, 'Matthew 7:4', 'Matthew', 7, 4, '&nbsp;او تۀ څنګه خپل ورور ته دا وئيلے شې چې، راشه چې ستا د سترګې نه دا خسڼے وباسم، خو حال دا چې په خپله سترګه کښې درته تير نۀ ښکارى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22206, 'Matthew 7:5', 'Matthew', 7, 5, '&nbsp;اے رياکاره، اول د خپلې سترګې نه تير وباسه، نو بيا به ستا سترګې وغړيږى چې د خپل ورور د سترګې نه خسڼے وباسې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22207, 'Matthew 7:6', 'Matthew', 7, 6, '&nbsp;پاک څيزونه سپو له مۀ ورکوئ، خپلې ملغلرې خنزيرانو ته مۀ غورزوئ. هغوئ به يې د پښو لاندې کړى او په تاسو به راوګرځى او ريچې ريچې به مو کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22208, 'Matthew 7:7', 'Matthew', 7, 7, '&nbsp;وغواړئ نو تاسو له به درکړے شى، ولټوئ نو تاسو به يې ومومئ، ور وټکوئ نو درته به کولاو کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22209, 'Matthew 7:8', 'Matthew', 7, 8, '&nbsp;ځکه هر څوک چې يې غواړى، هغۀ ته ملاويږى، او څوک يې چې لټون کوى، هغه يې مومى، او څوک چې ور ټکوى، هغۀ ته کولاويږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22210, 'Matthew 7:9', 'Matthew', 7, 9, '&nbsp;په تاسو کښې داسې څوک شته چې زوئ ترې روټۍ وغواړى او هغه به ورله کاڼے ورکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22211, 'Matthew 7:10', 'Matthew', 7, 10, '&nbsp;او يا دا چې ورنه کب وغواړى نو مار به ورکړى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22212, 'Matthew 7:11', 'Matthew', 7, 11, '&nbsp;نو کۀ بيا تاسو چې دومره ګناهګاران يئ، په دې پوهېږئ چې خپل اولاد له ښۀ څيزونه ورکړئ، نو ستاسو آسمانى پلار به څومره ښۀ څيزونه هغه چا له ورکړى چې څوک يې ترېنه غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22213, 'Matthew 7:12', 'Matthew', 7, 12, '&nbsp;د نورو سره تل داسې سلوک کوئ لکه څنګه سلوک چې تاسو د ځان دپاره خوښوئ، دا د شريعت او د ټولو نبيانو د تعليم مجموعه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22214, 'Matthew 7:13', 'Matthew', 7, 13, '&nbsp;په تنګه دروازه ورداخل شئ. ځکه چې د تباهۍ دروازه کولاو ده، لاره يې ښۀ پلنه ده او ډېر په دغه لاره ځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22215, 'Matthew 7:14', 'Matthew', 7, 14, '&nbsp;خو کومه دروازه چې د ژوند په لورې ده هغه وړه ده او لاره يې تنګه ده، او د دې پېدا کوونکى هم لږ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22216, 'Matthew 7:15', 'Matthew', 7, 15, '&nbsp;د دروغژنو نبيانو نه خبردار شئ، داسې کسان چې د ګډو په شکل کښې تاسو له راځى او په اصل کښې هغه داړونکى شرمخان دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22217, 'Matthew 7:16', 'Matthew', 7, 16, '&nbsp;تاسو به هغوئ په خپله مېوه وپېژنئ. ولې د ازغو جاړو بوټو نه څوک انګور، يا د جاخو نه څوک اينځر راشوکولے شى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22218, 'Matthew 7:17', 'Matthew', 7, 17, '&nbsp;هم دغه شان ښه ونه ښه مېوه نيسى او د بدې ونې مېوه بده وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22219, 'Matthew 7:18', 'Matthew', 7, 18, '&nbsp;ښه ونه بده مېوه نۀ شى نيولے او بده ونه ښه مېوه نۀ شى نيولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22220, 'Matthew 7:19', 'Matthew', 7, 19, '&nbsp;او کومه ونه چې ښه مېوه نۀ نيسى هغه به پرې کړے شى او په اور کښې به وغورزولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22221, 'Matthew 7:20', 'Matthew', 7, 20, '&nbsp;ځکه زۀ وايم چې تاسو به هغوئ په خپله مېوه وپېژنئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22222, 'Matthew 7:21', 'Matthew', 7, 21, '&nbsp;هر هغه څوک چې ما ته مالِک مالِک وائى هغه به د آسمان په بادشاهۍ کښې ورداخل نۀ شى، خو صرف هغه کس چې زما د آسمانى پلار په رضا کار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22223, 'Matthew 7:22', 'Matthew', 7, 22, '&nbsp;په ورځ د قيامت به ډېر ما ته وائى چې مالِکه، مالِکه، مونږ ستا په نوم نبوت نۀ وو کړے څۀ؟ او ستا په نوم مو پيريان نۀ وُو شړلى څۀ؟ او هم ستا په نوم مو ډيرې معجزې نۀ وې ښکاره کړې څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22224, 'Matthew 7:23', 'Matthew', 7, 23, '&nbsp;نو زۀ به هغوئ ته په ښکاره ووايم چې ما تاسو چرې هم نۀ يئ پېژندلى، تاسو بې‌شرعې خلق زما نه ورک شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22225, 'Matthew 7:24', 'Matthew', 7, 24, '&nbsp;هر هغه څوک چې زما دا خبرې اورى او عمل پرې کوى، هغه به د هغه هوښيار کس په شان وګڼلے شى چا چې خپل کور د يو سخت ګټ دپاسه آباد کړے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22226, 'Matthew 7:25', 'Matthew', 7, 25, '&nbsp;او چې باران وشو، سېلاب راغلو، زل زول او طوفان تير شو او د دۀ کور سره يې ډغرې وخوړې، خو دا راپرې نۀ وتو ځکه چې بنيادونه يې د يو سخت ګټ دپاسه وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22227, 'Matthew 7:26', 'Matthew', 7, 26, '&nbsp;خو د هغه چا به بيا څۀ اَنجام وى چې زما دا خبرې اورى او عمل پرې نۀ کوى؟ د هغۀ مِثال د هغه ناپوهه کس دے چا چې په شګو خپل کور جوړ کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22228, 'Matthew 7:27', 'Matthew', 7, 27, '&nbsp;باران وورېدو، سېلاب راغلو، زول او طوفان تېر شو او د دغه کور سره يې ډغرې وخوړې او راوې غورزولو او بلکل يې تباه کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22229, 'Matthew 7:28', 'Matthew', 7, 28, '&nbsp;څۀ وخت چې عيسىٰ دا خبرې بس کړې نو خلق د هغۀ په تعليم حق حېران شول،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22230, 'Matthew 7:29', 'Matthew', 7, 29, '&nbsp;ځکه چې هغۀ د هغوئ د شرعې عالمانو په شان نه، خو په پوره اختيار سره يې تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22231, 'Matthew 8:1', 'Matthew', 8, 1, '&nbsp;څۀ وخت چې عيسىٰ د غرۀ نه راکوز شو نو ګڼ خلق ورپسې شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22232, 'Matthew 8:2', 'Matthew', 8, 2, '&nbsp;خو بيا يو جذامى وروړاندې شو او په سجده ورته پرېوتو او وې وئيل، ”مالِکه، کۀ تۀ صرف وغواړې نو ما روغولے شې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22233, 'Matthew 8:3', 'Matthew', 8, 3, '&nbsp;عيسىٰ خپل لاس وراوږد کړو او په هغۀ يې کېښودو او وې فرمائيل چې، ”آو، زۀ غواړم چې داسې وکړم.“ بيا يې وفرمائيل چې، ”پاک شه.“ او په هغه ساعت د جذام نه روغ جوړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22234, 'Matthew 8:4', 'Matthew', 8, 4, '&nbsp;بيا عيسىٰ هغۀ ته وفرمائيل، ”ګوره چې هيچا ته د دې په حقله څۀ ونۀ وائې. خو لاړ شه او خپل ځان اِمام ته وښايه او کومه شکرانه چې موسىٰ مقرره کړې ده، هغه ورکړه. دا به ستا د روغولو ګواهى شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22235, 'Matthew 8:5', 'Matthew', 8, 5, '&nbsp;او کله چې عيسىٰ کفرنحُوم ښار ته وردننه شو نو يو رومى صوبه دار ورغلو او هغۀ ته يې مِنت وکړو او وئيل يې چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22236, 'Matthew 8:6', 'Matthew', 8, 6, '&nbsp;”مالِکه، زما يو نوکر په کور کښې شل ګوډ پروت دے او ډېر په تکليف کښې دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22237, 'Matthew 8:7', 'Matthew', 8, 7, '&nbsp;عيسىٰ ورته وفرمائيل، ”زۀ به درشم او روغ به يې کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22238, 'Matthew 8:8', 'Matthew', 8, 8, '&nbsp;خو صوبه دار جواب ورکړو چې، ”مالِکه، زۀ د دې جوګه نۀ يم چې تۀ زما کور ته راشې. خو کۀ تاسو صرف حکم وکړئ نو زما نوکر به جوړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22239, 'Matthew 8:9', 'Matthew', 8, 9, '&nbsp;ځکه چې زۀ پوهېږم چې زۀ په خپله د بل د حکم لاندې يم او سپاهيان زما د حکم لاندې دى. زۀ چې يو ته ووايم چې لاړ شه نو هغه لاړ شى، او چې بل ته ووايم چې دېخوا راشه، نو هغه راشى او چې خپل غلام ته ووايم چې داسې وکړه نو هغه يې هغه شان کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22240, 'Matthew 8:10', 'Matthew', 8, 10, '&nbsp;عيسىٰ په حېرانتيا د هغۀ خبرې واورېدې نو هغه ګڼې ته يې وفرمائيل چې، ”زۀ تاسو ته رښتيا وايم چې ما داسې ايمان په بنى اِسرائيلو کښې چرته هم نۀ دے ليدلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22241, 'Matthew 8:11', 'Matthew', 8, 11, '&nbsp;زۀ تاسو ته دا وايم چې د نمرخاتۀ او د نمرپرېواتۀ نه به ډېر خلق داسې راشى چې د اِبراهيم، اِسحاق او يعقوب سره به د آسمان د بادشاهۍ په مېلمستيا کښې يو ځائ کښېنى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22242, 'Matthew 8:12', 'Matthew', 8, 12, '&nbsp;خو د بادشاهت وارثان به بهر تيارې ته وغورزولے شى کوم ځائ چې به ژړا وير او د غاښونو چيچل وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22243, 'Matthew 8:13', 'Matthew', 8, 13, '&nbsp;بيا عيسىٰ صوبه دار ته وفرمائيل چې، ”اوس خپل کور ته لاړ شه، نو ستا د ايمان په وجه دې داسې وشى.“ نو هم په هغه ساعت د هغۀ نوکر روغ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22244, 'Matthew 8:14', 'Matthew', 8, 14, '&nbsp;عيسىٰ بيا د پطروس کور ته لاړو او وې ليدل چې د پطروس خواښې تبې نيولې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22245, 'Matthew 8:15', 'Matthew', 8, 15, '&nbsp;نو د هغې لاس ته يې لاس وروړو نو د هغې نه تبه لاړه. هغه پاڅېده او د هغۀ په خِدمت کولو شروع شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22246, 'Matthew 8:16', 'Matthew', 8, 16, '&nbsp;کله چې ماښام شو نو خلقو عيسىٰ له ډېر داسې کسان راوستل چې پيريانو نيولى وُو او هغۀ د هغوئ نه په يو حکم پيريان وشړل او ټول بيماران يې روغ کړل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22247, 'Matthew 8:17', 'Matthew', 8, 17, '&nbsp;چې دغه شان د يشعياه نبى په وسيله وئيلے شوې هغه پېشګوئې پوره شى چې، ”هغۀ زمونږ بيمارۍ او کمزورۍ اوچتې کړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22248, 'Matthew 8:18', 'Matthew', 8, 18, '&nbsp;عيسىٰ چې د ځان نه چاپېره ګڼه وليده نو حکم يې وکړو چې راځئ چې د درياب پورې غاړې ته لاړ شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22249, 'Matthew 8:19', 'Matthew', 8, 19, '&nbsp;يو د شرعې عالم ورغلو او وې وئيل چې، ”اُستاذه، هر چرته چې تۀ ځې، زۀ به هم درپسې ځم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22250, 'Matthew 8:20', 'Matthew', 8, 20, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”د لومبړو خپل غارونه وى او د مارغانو جالې، خو اِبن آدم دومره ځائ قدرې هم نۀ لرى چې سر پرې ولګوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22251, 'Matthew 8:21', 'Matthew', 8, 21, '&nbsp;يو بل مريد ورته ووئيل، ”مالِکه، اول ما ته اجازت راکړه چې خپل پلار ښخ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
